# Check if id_provider is not set to ad (Active Directory) which makes start_tls not applicable, note the -v option to invert the grep. # Try to find [domain/..] and ldap_tls_reqcert in sssd.conf, if it exists, set to 'demand' # if ldap_tls_reqcert isn't here, add it # if [domain/..] doesn't exist, add it here for default domain if grep -qvzosP $AD_REGEX $SSSD_CONF; then if grep -qzosP $LDAP_REGEX $SSSD_CONF; then
sed -i "s#ldap_tls_reqcert[^(
)]*#ldap_tls_reqcert = demand#" $SSSD_CONF elif grep -qs $DOMAIN_REGEX $SSSD_CONF; then sed -i "/$DOMAIN_REGEX/a ldap_tls_reqcert = demand" $SSSD_CONF else if test -f "$SSSD_CONF"; then echo -e "[domain/default]
ldap_tls_reqcert = demand" >> $SSSD_CONF else echo "Config file '$SSSD_CONF' doesnt exist, not remediating, assuming non-applicability." >&2 fi fi fi
readarray -t SSSD_CONF_D_FILES < <(find /etc/sssd/conf.d/ -name "*.conf") for SSSD_CONF_D_FILE in "${SSSD_CONF_D_FILES[@]}"; do sed -i "s#ldap_tls_reqcert[^(
